+import type { ContributionWeek } from '../types/github';
+
+export interface ContributionStats {
+  total: number;
+  currentStreak: number;
+  longestStreak: number;
+  avgPerActiveDay: number;
+}
+
+/**
+ * Compute contribution statistics from weeks data
+ */
+export function computeContributionStats(weeks: ContributionWeek[]): ContributionStats {
+  let total = 0;
+  let currentStreak = 0;
+  let longestStreak = 0;
+  let tempStreak = 0;
+  let activeDays = 0;
+  let totalOnActiveDays = 0;
+  
+  // Flatten all days
+  const allDays = weeks.flatMap(week => week.contributionDays);
+  
+  // Calculate total and streaks
+  const today = new Date();
+  today.setHours(0, 0, 0, 0);
+  
+  // Process days from most recent to oldest for current streak
+  const sortedDays = [...allDays].sort((a, b) => 
+    new Date(b.date).getTime() - new Date(a.date).getTime()
+  );
+  
+  let streakActive = true;
+  for (const day of sortedDays) {
+    total += day.count;
+    
+    if (day.count > 0) {
+      activeDays++;
+      totalOnActiveDays += day.count;
+    }
+    
+    // Calculate current streak (from today backwards)
+    if (streakActive) {
+      const dayDate = new Date(day.date);
+      dayDate.setHours(0, 0, 0, 0);
+      
+      // Allow for a 1-day gap (today or yesterday)
+      const daysDiff = Math.floor((today.getTime() - dayDate.getTime()) / (1000 * 60 * 60 * 24));
+      
+      if (day.count > 0 && daysDiff <= currentStreak + 1) {
+        currentStreak++;
+      } else if (daysDiff > 1) {
+        streakActive = false;
+      }
+    }
+  }
+  
+  // Calculate longest streak by iterating forward through time
+  const forwardDays = [...allDays].sort((a, b) => 
+    new Date(a.date).getTime() - new Date(b.date).getTime()
+  );
+  
+  for (const day of forwardDays) {
+    if (day.count > 0) {
+      tempStreak++;
+      longestStreak = Math.max(longestStreak, tempStreak);
+    } else {
+      tempStreak = 0;
+    }
+  }
+  
+  const avgPerActiveDay = activeDays > 0 ? Math.round(totalOnActiveDays / activeDays) : 0;
+  
+  return {
+    total,
+    currentStreak,
+    longestStreak,
+    avgPerActiveDay,
+  };
+}
+
+/**
+ * Compute power index from user stats
+ */
+export function computePowerIndex(stats: {
+  total: number;
+  followers: number;
+  publicRepos: number;
+  longestStreak: number;
+}): number {
+  const powerIndex = 
+    stats.total * 0.5 + 
+    stats.followers * 8 + 
+    stats.publicRepos * 5 + 
+    stats.longestStreak * 3;
+  
+  return Math.round(powerIndex);
+}
+
+/**
+ * Get account age from created_at date
+ */
+export function getAccountAge(createdAt: string): string {
+  const created = new Date(createdAt);
+  const year = created.getFullYear();
+  return `Since ${year}`;
+}
